const questions = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed languages?',
    helpText: 'Statically typed languages perform type checking at compile time.',
    options: ['Java', 'C++', 'Python', 'JavaScript'],
    correct: ['Java', 'C++']
  },
  {
    id: 'q2',
    text: 'Which languages are commonly used for systems programming?',
    options: ['C', 'Rust', 'Ruby', 'PHP'],
    correct: ['C', 'Rust']
  },
  {
    id: 'q3',
    text: 'Which of these are high-level programming languages?',
    options: ['Python', 'JavaScript', 'Assembly', 'C'],
    correct: ['Python', 'JavaScript']
  }
];

function Quiz() {
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (qId, option) => {
    const current = selected[qId] || [];
    const next = current.includes(option)
      ? current.filter(o => o !== option)
      : [...current, option];

    setSelected({ ...selected, [qId]: next });
  };

